/** @typedef {{ id: number; name: string; price: number; inventory: number }} Product */

/** @type {Product[]} */
let products = [
  { id: 1, name: 'Laptop', price: 999, inventory: 42 },
  { id: 2, name: 'Phone', price: 699, inventory: 128 },
  { id: 3, name: 'Tablet', price: 499, inventory: 67 },
  { id: 4, name: 'Headphones', price: 199, inventory: 240 },
  { id: 5, name: 'Watch', price: 299, inventory: 91 },
]

export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return products.map((product) => ({ ...product }))
}

/** Simulates a long-running ERP/PIM catalog sync. */
export async function syncCatalogFromERP() {
  await new Promise((resolve) => setTimeout(resolve, 1500))

  products = products.map((product) => ({
    ...product,
    price: Math.round(product.price * (0.97 + Math.random() * 0.06)),
    inventory: Math.max(
      0,
      product.inventory + Math.floor(Math.random() * 21) - 10,
    ),
  }))
}

